-- Projects and portfolio cell (projects), generated by solo-cell-kit from cell.yaml.
-- Every row belongs to a workspace and is visible only while the transaction
-- is bound to it (app.workspace_id). Do not edit once applied; add a new migration.

CREATE SCHEMA projects;

CREATE FUNCTION projects.current_workspace() RETURNS uuid
LANGUAGE sql STABLE AS $$
    SELECT nullif(current_setting('app.workspace_id', true), '')::uuid
$$;

CREATE TABLE projects.projects (
    workspace_id             uuid NOT NULL,
    id                       bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000000),
    legacy_id                bigint,
    name                     text NOT NULL CHECK (length(name) <= 500 AND length(name) >= 1),
    slug                     text NOT NULL CHECK (length(slug) <= 200 AND length(slug) >= 1),
    description              text,
    category                 text NOT NULL DEFAULT 'product' CHECK (category IN ('product', 'client', 'internal', 'experiment', 'portfolio', 'open_source')),
    type                     text CHECK (type IS NULL OR (length(type) <= 100)),
    status                   text NOT NULL DEFAULT 'idea' CHECK (status IN ('idea', 'planning', 'active', 'paused', 'completed', 'abandoned', 'archived')),
    priority                 integer NOT NULL DEFAULT 3,
    start_date               date,
    target_launch            date,
    launched_at              date,
    completed_at             date,
    progress_percent         integer NOT NULL DEFAULT 0 CHECK (progress_percent >= 0 AND progress_percent <= 100),
    phase                    text CHECK (phase IS NULL OR (length(phase) <= 200)),
    revenue_model            text,
    monthly_revenue          double precision NOT NULL DEFAULT 0,
    total_revenue            double precision NOT NULL DEFAULT 0,
    tech_stack               text,
    repo_url                 text,
    live_url                 text,
    docs_url                 text,
    notes                    text,
    color                    text CHECK (color IS NULL OR (length(color) <= 40)),
    parent_project_id        bigint,
    task_count               integer NOT NULL DEFAULT 0,
    completed_count          integer NOT NULL DEFAULT 0,
    archived_at              timestamptz,
    domain                   text CHECK (domain IS NULL OR (length(domain) <= 200)),
    version                  bigint NOT NULL DEFAULT 1,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, id),
    UNIQUE (workspace_id, slug),
    FOREIGN KEY (workspace_id, parent_project_id) REFERENCES projects.projects (workspace_id, id)
);
CREATE UNIQUE INDEX projects_legacy ON projects.projects (workspace_id, legacy_id) WHERE legacy_id IS NOT NULL;
CREATE INDEX projects_category ON projects.projects (workspace_id, category);
CREATE INDEX projects_domain ON projects.projects (workspace_id, domain);
CREATE INDEX projects_parent_project_id ON projects.projects (workspace_id, parent_project_id);
CREATE INDEX projects_priority ON projects.projects (workspace_id, priority);
CREATE INDEX projects_status ON projects.projects (workspace_id, status);
CREATE INDEX projects_type ON projects.projects (workspace_id, type);

CREATE TABLE projects.portfolio_contexts (
    workspace_id             uuid NOT NULL,
    id                       bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000000),
    legacy_id                bigint,
    slug                     text NOT NULL CHECK (length(slug) <= 200 AND length(slug) >= 1),
    name                     text NOT NULL CHECK (length(name) <= 500 AND length(name) >= 1),
    context_type             text NOT NULL CHECK (context_type IN ('personal', 'hobby', 'learning', 'freelance', 'startup', 'venture', 'client_engagement', 'internal', 'business_system', 'workspace', 'role_capability', 'unclassified')),
    scope                    text NOT NULL DEFAULT 'personal' CHECK (scope IN ('personal', 'professional', 'client', 'mixed')),
    parent_context_id        bigint,
    description              text,
    source_path              text,
    source                   text NOT NULL DEFAULT 'manual' CHECK (length(source) <= 200),
    status                   text NOT NULL DEFAULT 'active' CHECK (status IN ('planned', 'active', 'paused', 'completed', 'archived')),
    version                  bigint NOT NULL DEFAULT 1,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, id),
    UNIQUE (workspace_id, slug),
    FOREIGN KEY (workspace_id, parent_context_id) REFERENCES projects.portfolio_contexts (workspace_id, id)
);
CREATE UNIQUE INDEX portfolio_contexts_legacy ON projects.portfolio_contexts (workspace_id, legacy_id) WHERE legacy_id IS NOT NULL;
CREATE INDEX portfolio_contexts_context_type ON projects.portfolio_contexts (workspace_id, context_type);
CREATE INDEX portfolio_contexts_parent_context_id ON projects.portfolio_contexts (workspace_id, parent_context_id);
CREATE INDEX portfolio_contexts_scope ON projects.portfolio_contexts (workspace_id, scope);
CREATE INDEX portfolio_contexts_status ON projects.portfolio_contexts (workspace_id, status);

CREATE TABLE projects.project_repos (
    workspace_id             uuid NOT NULL,
    id                       bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000000),
    legacy_id                bigint,
    project_id               bigint,
    repo_name                text NOT NULL CHECK (length(repo_name) <= 300 AND length(repo_name) >= 1),
    repo_url                 text,
    role                     text NOT NULL DEFAULT 'fullstack' CHECK (role IN ('frontend', 'backend', 'fullstack', 'docs', 'infra', 'script', 'mobile', 'other')),
    language                 text CHECK (language IS NULL OR (length(language) <= 100)),
    is_primary               boolean NOT NULL DEFAULT false,
    version                  bigint NOT NULL DEFAULT 1,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, id),
    UNIQUE (workspace_id, project_id, repo_name),
    FOREIGN KEY (workspace_id, project_id) REFERENCES projects.projects (workspace_id, id)
);
CREATE UNIQUE INDEX project_repos_legacy ON projects.project_repos (workspace_id, legacy_id) WHERE legacy_id IS NOT NULL;
CREATE INDEX project_repos_is_primary ON projects.project_repos (workspace_id, is_primary);
CREATE INDEX project_repos_project_id ON projects.project_repos (workspace_id, project_id);
CREATE INDEX project_repos_role ON projects.project_repos (workspace_id, role);

CREATE TABLE projects.project_context_links (
    workspace_id             uuid NOT NULL,
    id                       bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000000),
    legacy_id                bigint,
    project_id               bigint NOT NULL,
    context_id               bigint NOT NULL,
    relation_type            text NOT NULL DEFAULT 'primary' CHECK (relation_type IN ('primary', 'supporting')),
    weight                   double precision NOT NULL DEFAULT 1 CHECK (weight >= 0.0001),
    source                   text NOT NULL DEFAULT 'manual' CHECK (length(source) <= 200),
    version                  bigint NOT NULL DEFAULT 1,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, id),
    UNIQUE (workspace_id, project_id, context_id),
    FOREIGN KEY (workspace_id, project_id) REFERENCES projects.projects (workspace_id, id),
    FOREIGN KEY (workspace_id, context_id) REFERENCES projects.portfolio_contexts (workspace_id, id)
);
CREATE UNIQUE INDEX project_context_links_legacy ON projects.project_context_links (workspace_id, legacy_id) WHERE legacy_id IS NOT NULL;
CREATE INDEX project_context_links_context_id ON projects.project_context_links (workspace_id, context_id);
CREATE INDEX project_context_links_project_id ON projects.project_context_links (workspace_id, project_id);
CREATE INDEX project_context_links_relation_type ON projects.project_context_links (workspace_id, relation_type);

CREATE TABLE projects.work_items (
    workspace_id             uuid NOT NULL,
    id                       bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000000),
    legacy_id                bigint,
    item_type                text NOT NULL CHECK (item_type IN ('epic', 'story')),
    title                    text NOT NULL CHECK (length(title) <= 500 AND length(title) >= 1),
    description              text,
    goal_id                  bigint,
    project_id               bigint NOT NULL,
    parent_item_id           bigint,
    status                   text NOT NULL DEFAULT 'todo' CHECK (status IN ('todo', 'in_progress', 'done', 'blocked', 'cancelled')),
    progress_percent         integer NOT NULL DEFAULT 0 CHECK (progress_percent >= 0 AND progress_percent <= 100),
    weight                   double precision NOT NULL DEFAULT 1 CHECK (weight >= 0.0001),
    source_key               text NOT NULL CHECK (length(source_key) <= 300 AND length(source_key) >= 1),
    source                   text NOT NULL DEFAULT 'manual' CHECK (length(source) <= 200),
    version                  bigint NOT NULL DEFAULT 1,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, id),
    UNIQUE (workspace_id, source_key),
    FOREIGN KEY (workspace_id, project_id) REFERENCES projects.projects (workspace_id, id),
    FOREIGN KEY (workspace_id, parent_item_id) REFERENCES projects.work_items (workspace_id, id)
);
CREATE UNIQUE INDEX work_items_legacy ON projects.work_items (workspace_id, legacy_id) WHERE legacy_id IS NOT NULL;
CREATE INDEX work_items_goal_id ON projects.work_items (workspace_id, goal_id);
CREATE INDEX work_items_item_type ON projects.work_items (workspace_id, item_type);
CREATE INDEX work_items_parent_item_id ON projects.work_items (workspace_id, parent_item_id);
CREATE INDEX work_items_project_id ON projects.work_items (workspace_id, project_id);
CREATE INDEX work_items_source_key ON projects.work_items (workspace_id, source_key);
CREATE INDEX work_items_status ON projects.work_items (workspace_id, status);

CREATE TABLE projects.work_item_task_links (
    workspace_id             uuid NOT NULL,
    id                       bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000000),
    legacy_id                bigint,
    work_item_id             bigint NOT NULL,
    task_id                  bigint NOT NULL,
    relation_type            text NOT NULL DEFAULT 'implements' CHECK (relation_type IN ('implements', 'supports')),
    weight                   double precision NOT NULL DEFAULT 1 CHECK (weight >= 0.0001),
    version                  bigint NOT NULL DEFAULT 1,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, id),
    UNIQUE (workspace_id, work_item_id, task_id),
    FOREIGN KEY (workspace_id, work_item_id) REFERENCES projects.work_items (workspace_id, id)
);
CREATE UNIQUE INDEX work_item_task_links_legacy ON projects.work_item_task_links (workspace_id, legacy_id) WHERE legacy_id IS NOT NULL;
CREATE INDEX work_item_task_links_relation_type ON projects.work_item_task_links (workspace_id, relation_type);
CREATE INDEX work_item_task_links_task_id ON projects.work_item_task_links (workspace_id, task_id);
CREATE INDEX work_item_task_links_work_item_id ON projects.work_item_task_links (workspace_id, work_item_id);

CREATE TABLE projects.work_item_goal_task_links (
    workspace_id             uuid NOT NULL,
    id                       bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000000),
    legacy_id                bigint,
    work_item_id             bigint NOT NULL,
    goal_task_id             bigint NOT NULL,
    relation_type            text NOT NULL DEFAULT 'implements' CHECK (relation_type IN ('implements', 'supports')),
    weight                   double precision NOT NULL DEFAULT 1 CHECK (weight >= 0.0001),
    version                  bigint NOT NULL DEFAULT 1,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, id),
    UNIQUE (workspace_id, work_item_id, goal_task_id),
    FOREIGN KEY (workspace_id, work_item_id) REFERENCES projects.work_items (workspace_id, id)
);
CREATE UNIQUE INDEX work_item_goal_task_links_legacy ON projects.work_item_goal_task_links (workspace_id, legacy_id) WHERE legacy_id IS NOT NULL;
CREATE INDEX work_item_goal_task_links_goal_task_id ON projects.work_item_goal_task_links (workspace_id, goal_task_id);
CREATE INDEX work_item_goal_task_links_relation_type ON projects.work_item_goal_task_links (workspace_id, relation_type);
CREATE INDEX work_item_goal_task_links_work_item_id ON projects.work_item_goal_task_links (workspace_id, work_item_id);

-- Idempotent creates: a key reserves the record id before the platform execution starts.
CREATE TABLE projects.create_keys (
    workspace_id uuid NOT NULL,
    actor        uuid NOT NULL,
    kind         text NOT NULL CHECK (kind IN ('project', 'project-repo', 'portfolio-context', 'project-context-link', 'work-item', 'work-item-task-link', 'work-item-goal-task-link')),
    key          text NOT NULL CHECK (length(key) BETWEEN 8 AND 200),
    record_id    bigint NOT NULL,
    created_at   timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, actor, kind, key)
);

-- Graph events, written in the same transaction as the change (at-least-once delivery).
CREATE TABLE projects.outbox (
    id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    workspace_id    uuid NOT NULL,
    type            text NOT NULL,
    subject         text NOT NULL,
    execution_id    uuid,
    classification  text NOT NULL DEFAULT 'confidential',
    payload         jsonb NOT NULL,
    occurred_at     timestamptz NOT NULL DEFAULT now(),
    published_at    timestamptz,
    attempts        integer NOT NULL DEFAULT 0,
    next_attempt_at timestamptz NOT NULL DEFAULT now(),
    last_error      text,
    correlation_id  text
);
CREATE INDEX outbox_pending ON projects.outbox (next_attempt_at) WHERE published_at IS NULL;

DO $$
DECLARE
    t text;
BEGIN
    FOREACH t IN ARRAY ARRAY['projects', 'portfolio_contexts', 'project_repos', 'project_context_links', 'work_items', 'work_item_task_links', 'work_item_goal_task_links', 'create_keys', 'outbox'] LOOP
        EXECUTE format('ALTER TABLE projects.%I ENABLE ROW LEVEL SECURITY', t);
        EXECUTE format('ALTER TABLE projects.%I FORCE ROW LEVEL SECURITY', t);
        EXECUTE format('CREATE POLICY workspace_isolation ON projects.%I'
                       ' USING (workspace_id = projects.current_workspace())'
                       ' WITH CHECK (workspace_id = projects.current_workspace())', t);
    END LOOP;
END
$$;

GRANT USAGE ON SCHEMA projects TO projects_api;
GRANT EXECUTE ON FUNCTION projects.current_workspace() TO projects_api;
GRANT SELECT, INSERT, UPDATE, DELETE ON projects.projects, projects.portfolio_contexts, projects.project_repos, projects.project_context_links, projects.work_items, projects.work_item_task_links, projects.work_item_goal_task_links TO projects_api;
GRANT USAGE ON SEQUENCE projects.projects_id_seq, projects.portfolio_contexts_id_seq, projects.project_repos_id_seq, projects.project_context_links_id_seq, projects.work_items_id_seq, projects.work_item_task_links_id_seq, projects.work_item_goal_task_links_id_seq TO projects_api;
GRANT SELECT, INSERT ON projects.create_keys TO projects_api;
GRANT SELECT, INSERT ON projects.outbox TO projects_api;
GRANT UPDATE (execution_id, published_at, attempts, next_attempt_at, last_error) ON projects.outbox TO projects_api;

-- The publisher sweeps the outbox of one workspace per token; it reads past RLS for the outbox only.
CREATE POLICY publisher_sweep ON projects.outbox TO projects_publisher USING (true) WITH CHECK (true);
GRANT USAGE ON SCHEMA projects TO projects_publisher;
GRANT SELECT ON projects.outbox TO projects_publisher;
GRANT UPDATE (published_at, attempts, next_attempt_at, last_error) ON projects.outbox TO projects_publisher;
